body = Map();
body.put("data", batch);
// trigger:[] suppresses workflows for bulk paths where the caller is
// already maintaining the rollups itself - prevents N workflow storms.
body.put("trigger", List());

// invokeurl needs a literal HTTP verb, so the two paths are spelled out.
resp = Map();
if(method == "POST")
{
    resp = invokeurl
    [
        url        : "https://www.zohoapis.in/crm/v5/" + moduleName
        type       : POST
        parameters : body.toString()
        headers    : {"Content-Type":"application/json"}
        connection : "crmconn"
    ];
}
else
{
    resp = invokeurl
    [
        url        : "https://www.zohoapis.in/crm/v5/" + moduleName
        type       : PUT
        parameters : body.toString()
        headers    : {"Content-Type":"application/json"}
        connection : "crmconn"
    ];
}

ok = 0;
if(!isNull(resp.get("data")))
{
    iter_r = resp.get("data").toList();
    for each r in iter_r
    {
        if(r.get("code") == "SUCCESS")
        {
            ok = ok + 1;
        }
        else if(r.get("code") != "DUPLICATE_DATA")
        {
            // DUPLICATE_DATA is expected and harmless - it is the unique-key
            // guard doing its job. Anything else is worth logging.
            info moduleName + " batch item failed: " + r.toString();
        }
    }
}
else
{
    info moduleName + " batch call failed: " + resp.toString();
}
return ok;

